# Statuses that were publicly listed before publication became its own step.
PREVIOUSLY_LISTED = ['approved', 'active', 'tokenized']


def keep_current_listings_published(apps, schema_editor):
    """Everything that is listed today stays listed, so nothing live vanishes."""
    Property = apps.get_model('properties', 'Property')
    PropertyApproval = apps.get_model('properties', 'PropertyApproval')
    for prop in Property.objects.filter(status__in=PREVIOUSLY_LISTED):
        prop.is_published = True
        prop.published_at = prop.updated_at
        prop.save(update_fields=['is_published', 'published_at'])
        # Seeded listings never went through review; record them as approved
        # so admins can unpublish / republish them with the normal workflow.
        if not PropertyApproval.objects.filter(property_id=prop.pk).exists():
            PropertyApproval.objects.create(property_id=prop.pk, status='approved',
                                            approved_at=prop.updated_at,
                                            reviewed_at=prop.updated_at)


def noop(apps, schema_editor):
    pass


